function validate([edges]) {
  if (!Array.isArray(edges) || edges.length > 9999) return 'edges holds at most 9,999 edges (n is at most 10,000).';
  const n = edges.length + 1;
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => {
    while (root[x] !== x) {
      root[x] = root[root[x]];
      x = root[x];
    }
    return x;
  };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || !edge.every(v => Number.isInteger(v) && v >= 0 && v < n)) return `Each edge is [a, b] with nodes from 0 to ${n - 1}.`;
    if (edge[0] === edge[1]) return 'An edge must join two different nodes.';
    const ra = find(edge[0]);
    const rb = find(edge[1]);
    if (ra === rb) return 'The edges must form a tree: an edge repeats or closes a cycle.';
    root[ra] = rb;
  }
  return null;
}

