function treeDiameter(edges) {
  const n = edges.length + 1;
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        order.push(next);
      }
    }
  }

  const down = new Array(n).fill(0);
  let diameter = 0;
  for (let i = n - 1; i > 0; i--) {
    const node = order[i];
    const top = parent[node];
    const branch = down[node] + 1;
    diameter = Math.max(diameter, down[top] + branch);
    down[top] = Math.max(down[top], branch);
  }
  return diameter;
}

