function treeDiameter(edges) {
  // Measure the distance between every pair of nodes with a BFS from each node.
  const n = edges.length + 1;
  const neighbours = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    neighbours[a].push(b);
    neighbours[b].push(a);
  }
  let longest = 0;
  for (let start = 0; start < n; start++) {
    const distance = new Array(n).fill(-1);
    distance[start] = 0;
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const u = queue[head];
      longest = Math.max(longest, distance[u]);
      for (const v of neighbours[u]) {
        if (distance[v] === -1) {
          distance[v] = distance[u] + 1;
          queue.push(v);
        }
      }
    }
  }
  return longest;
}

