function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const label = shuffle(Array.from({ length: n }, (_, i) => i));
  // Shapes: random, long and thin, bushy around a few hubs, and a complete binary tree.
  const shape = Math.floor(rand() * 4);
  const edges = [];
  for (let i = 1; i < n; i++) {
    let p;
    if (shape === 0) p = Math.floor(rand() * i);
    else if (shape === 1) p = Math.max(0, i - 1 - Math.floor(rand() * 3));
    else if (shape === 2) p = Math.floor(rand() * Math.min(i, 3));
    else p = Math.floor((i - 1) / 2);
    edges.push(rand() < 0.5 ? [label[i], label[p]] : [label[p], label[i]]);
  }
  return [shuffle(edges)];
}
